    reg [1:0] state, next_state;
    reg [1:0] next_state_table [0:3][0:1];
    reg [1:0] state_comb [0:3];
    reg [1:0] next_state_comb [0:3];
    reg [1:0] next_state_table_flat [0:7];
    reg [1:0] state_reg [0:3];
    reg [1:0] next_state_reg [0:3];
    reg [1:0] out_reg [0:3];
    integer i, j;

    always @(*) begin
        next_state_table[0][0] = 2'b00; next_state_table[0][1] = 2'b01;
