        next_state_table[3][0] = 2'b10; next_state_table[3][1] = 2'b01;
        for (i = 0; i < 4; i = i + 1) begin
            state_comb[i] = i;
            next_state_comb[i] = {next_state_table[i][in], next_state_table[i][~in]};
