            state_reg[i+1] = state_reg[i];
            next_state_reg[i+1] = next_state_reg[i];
            out_reg[i+1] = out_reg[i];
        end
        state_reg[0] = state;
        next_state_reg[0] = next_state_table_flat[state*2 + in];
        out_reg[0] = next_state_table[state][in];
        state = state_reg[2];
        next_state = next_state_reg[2];
    end
